mapper.select:
SELECT i.id AS item_id, i.type AS item_type, i.title AS item_title, i.description AS item_description, i.location AS item_location, i.image AS item_image, i.publisher_uid AS item_publisher_uid, i.publisher_name AS item_publisher_name, i.publisher_phone AS item_publisher_phone, i.publisher_student_id AS item_publisher_student_id, pu.avatar AS item_publisher_avatar, i.status AS item_status, i.views AS item_views, i.resolved_application_id AS item_resolved_application_id, i.returner_name AS item_returner_name, i.claimer_name AS item_claimer_name, i.return_time AS item_return_time, i.claim_time AS item_claim_time, i.is_deleted AS item_is_deleted, i.create_time AS item_create_time, i.update_time AS item_update_time, a.id AS application_id, a.status AS application_status, a.apply_type, a.applicant_uid, a.applicant_name, a.applicant_phone, a.applicant_student_id, a.applicant_id_card, au.avatar AS applicant_avatar FROM lost_found_item i LEFT JOIN user pu ON pu.uid = i.publisher_uid COLLATE utf8mb4_0900_ai_ci LEFT JOIN lost_found_application a ON a.item_id = i.id AND a.is_deleted = 0 AND a.status IN ('pending', 'approved', 'completed') AND ( a.id = i.resolved_application_id OR a.status IN ('pending', 'approved')
OR a.applicant_uid = #{userUid} OR i.publisher_uid = #{userUid}
) LEFT JOIN user au ON au.uid = a.applicant_uid COLLATE utf8mb4_0900_ai_ci WHERE i.is_deleted = 0
AND i.type = #{type}
AND i.status = #{status}
AND ( i.title LIKE CONCAT('%', #{keyword}, '%') OR i.description LIKE CONCAT('%', #{keyword}, '%') OR i.location LIKE CONCAT('%', #{keyword}, '%') OR i.publisher_name LIKE CONCAT('%', #{keyword}, '%') OR i.publisher_phone LIKE CONCAT('%', #{keyword}, '%') OR i.publisher_student_id LIKE CONCAT('%', #{keyword}, '%') OR i.returner_name LIKE CONCAT('%', #{keyword}, '%') OR i.claimer_name LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM lost_found_application ak WHERE ak.item_id = i.id AND ak.is_deleted = 0 AND ( ak.applicant_name LIKE CONCAT('%', #{keyword}, '%') OR ak.applicant_phone LIKE CONCAT('%', #{keyword}, '%') OR ak.applicant_student_id LIKE CONCAT('%', #{keyword}, '%') OR ak.applicant_id_card LIKE CONCAT('%', #{keyword}, '%') ) ) )
ORDER BY CASE WHEN i.status != 0 THEN 3 WHEN i.publisher_uid = #{userUid} THEN 0 WHEN a.applicant_uid = #{userUid} AND a.id IS NOT NULL AND a.status IN ('pending', 'approved') THEN 1 ELSE 2 END, i.create_time DESC, i.id DESC

SELECT i.id AS item_id, i.type AS item_type, i.title AS item_title, i.description AS item_description, i.location AS item_location, i.image AS item_image, i.publisher_uid AS item_publisher_uid, i.publisher_name AS item_publisher_name, i.publisher_phone AS item_publisher_phone, i.publisher_student_id AS item_publisher_student_id, pu.avatar AS item_publisher_avatar, i.status AS item_status, i.views AS item_views, i.resolved_application_id AS item_resolved_application_id, i.returner_name AS item_returner_name, i.claimer_name AS item_claimer_name, i.return_time AS item_return_time, i.claim_time AS item_claim_time, i.is_deleted AS item_is_deleted, i.create_time AS item_create_time, i.update_time AS item_update_time, a.id AS application_id, a.status AS application_status, a.apply_type, a.applicant_uid, a.applicant_name, a.applicant_phone, a.applicant_student_id, a.applicant_id_card, au.avatar AS applicant_avatar FROM lost_found_item i LEFT JOIN user pu ON pu.uid = i.publisher_uid COLLATE utf8mb4_0900_ai_ci LEFT JOIN lost_found_application a ON a.item_id = i.id AND a.is_deleted = 0 AND ( a.id = i.resolved_application_id OR a.status IN ('pending', 'approved')
OR a.applicant_uid = #{userUid} OR i.publisher_uid = #{userUid}
) LEFT JOIN user au ON au.uid = a.applicant_uid COLLATE utf8mb4_0900_ai_ci WHERE i.id = #{id} AND i.is_deleted = 0 ORDER BY a.create_time DESC LIMIT 1

SELECT COUNT(*)
FROM lost_found_application
WHERE item_id = #{itemId}
  AND applicant_uid = #{applicantUid}
  AND is_deleted = 0

mapper.update:
UPDATE lost_found_item
SET is_deleted = 1, update_time = NOW()
WHERE id = #{id}
  AND publisher_uid = #{userUid}
  AND is_deleted = 0

mapper.select:
SELECT i.id AS item_id, i.type AS item_type, i.title AS item_title, i.description AS item_description, i.location AS item_location, i.image AS item_image, i.publisher_uid AS item_publisher_uid, i.publisher_name AS item_publisher_name, i.publisher_phone AS item_publisher_phone, i.publisher_student_id AS item_publisher_student_id, pu.avatar AS item_publisher_avatar, i.status AS item_status, i.views AS item_views, i.resolved_application_id AS item_resolved_application_id, i.returner_name AS item_returner_name, i.claimer_name AS item_claimer_name, i.return_time AS item_return_time, i.claim_time AS item_claim_time, i.is_deleted AS item_is_deleted, i.create_time AS item_create_time, i.update_time AS item_update_time FROM lost_found_item i LEFT JOIN user pu ON i.publisher_uid = pu.uid WHERE i.is_deleted = 0 AND i.status = 'published' AND (
i.title LIKE CONCAT('%', #{kw}, '%') OR i.description LIKE CONCAT('%', #{kw}, '%') OR i.location LIKE CONCAT('%', #{kw}, '%')
) ORDER BY i.create_time DESC LIMIT #{limit}
